"""Upload to /content and run %run /content/APPLY_REFLECTION_COLAB.py.
Applies the completed report and readable figure, runs the original verifier;
never changes model configs, measured results, source manifest or judge outputs.
"""
from pathlib import Path
import base64, hashlib, json, subprocess, sys, zipfile
from datetime import datetime, timezone

ROOT = Path('/content/lab22')
REPORT = base64.b64decode('')
FIGURE = base64.b64decode('')
EXPECTED_VERIFY = '9c6a523841dbdb6c71c948bfa6d0f28f7619bf8e71fd54999453e2082617b895'
EXPECTED_OUTPUT = 'a4a292bd306942511d297ad0d282b146586216a26a52548edfdbc7404b343c35'
assert ROOT.is_dir(), 'Runtime /content/lab22 is missing; do not rerun training until backups are checked.'
checker = ROOT / 'scripts/verify.py'
assert checker.is_file() and hashlib.sha256(checker.read_bytes()).hexdigest() == EXPECTED_VERIFY, 'Original verifier differs/missing; stop and inspect.'
outputs = ROOT / 'data/eval/side_by_side.jsonl'
assert outputs.is_file() and hashlib.sha256(outputs.read_bytes()).hexdigest() == EXPECTED_OUTPUT, 'NB4 outputs differ from the audited run; stop and inspect.'
originals = ROOT / 'submission/colab_original'
originals.mkdir(parents=True, exist_ok=True)
for relative in ['REFLECTION.md', 'screenshots/04-side-by-side-table.png', 'verify_colab.txt', 'verify_status.json']:
    source = ROOT / 'submission' / relative
    dest = originals / relative
    if source.is_file() and not dest.exists():
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(source.read_bytes())
(ROOT / 'submission/REFLECTION.md').write_bytes(REPORT)
(ROOT / 'submission/screenshots/04-side-by-side-table.png').write_bytes(FIGURE)
record = {
    'student_name': 'Nguyễn Nhân Sâm', 'student_id': '2A202602672', 'student_class': '3A', 'course': 'IV',
    'updated_at': datetime.now(timezone.utc).isoformat(),
    'reflection_sha256': hashlib.sha256(REPORT).hexdigest(),
    'presentation_figure_sha256': hashlib.sha256(FIGURE).hexdigest(),
    'original_source_manifest_preserved': True, 'training_and_judge_outputs_changed': False,
    'note': 'Report filled after run; NB4 table reformatted from original records. Original files retained.'
}
(ROOT / 'submission/finalization.json').write_text(json.dumps(record, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
result = subprocess.run([sys.executable, str(checker)], cwd=ROOT, capture_output=True, text=True, encoding='utf-8')
log = result.stdout + result.stderr
print(log)
(ROOT / 'submission/verify_colab.txt').write_text(log, encoding='utf-8')
(ROOT / 'submission/verify_status.json').write_text(json.dumps({'exit_code': result.returncode}, indent=2)+'\n', encoding='utf-8')
assert result.returncode == 0, 'Full verify did not pass. Keep this log and send it back; no successful final ZIP was exported.'
sys.path.insert(0, str(ROOT))
from scripts.build_core_colab import export_evidence
archive = export_evidence(ROOT, ROOT / 'Lab22_Core_Evidence_Final.zip')
with zipfile.ZipFile(archive, 'a', compression=zipfile.ZIP_DEFLATED) as zipped:
    for path in sorted(originals.rglob('*')):
        if path.is_file() and path.suffix.lower() in {'.md', '.png', '.txt', '.json'}:
            zipped.write(path, path.relative_to(ROOT).as_posix())
print('Full verify exit 0. Also download File -> Download -> Download .ipynb to preserve executed outputs.')
from google.colab import files
files.download(str(archive))
